// 1. Recebe uma função e aplica duas vezes.
function aplicarDuasVezes(valor, transformacao) {
  return transformacao(transformacao(valor));
}

// 2. Devolve uma função sob medida (closure).
function criarAumentador(porcento) {
  return (preco) => preco * (1 + porcento);
}

// 3. Compõe duas funções: primeiro g, depois f.
function compor(f, g) {
  return (valor) => f(g(valor));
}

const aumentar10 = criarAumentador(0.1);
console.log(aumentar10(100)); // 110

console.log(aplicarDuasVezes(3, (n) => n * 2)); // 12

const gritar = compor((s) => s + '!', (s) => s.toUpperCase());
console.log(gritar('oi')); // 'OI!'

// Passo 1: transformações — cada uma com uma única responsabilidade.
const removerEspacos = (texto) => texto.trim();
const tornarMaiusculo = (texto) => texto.toUpperCase();
const adicionarPonto = (texto) => texto + '.';

// Passo 2: o pipeline recebe as transformações via rest.
function criarPipeline(...transformacoes) {
  // Passo 3: devolve uma função que aplica tudo em ordem.
  return function (texto) {
    let atual = texto;
    for (const transformacao of transformacoes) {
      atual = transformacao(atual); // a saída de uma entra na próxima
    }
    return atual;
  };
}

// Passo 4: reutilize as peças em ordens diferentes.
const limpar = criarPipeline(removerEspacos, adicionarPonto);
const gritar = criarPipeline(removerEspacos, tornarMaiusculo, adicionarPonto);

// Passo 5: confira.
console.log(limpar('  oi  '));   // 'oi.'
console.log(gritar('  oi  '));   // 'OI.'
